// spec: .qa/e2e/specs/promo-filter.md
// seed: tests/seed.hunter_free.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_free.json') });

const SECTION = 'מסלול קידום והפצה';
const TECH = 'טכנולוגיה, מוצר, דאטה ומערכות מידע';

test.describe('Promotion filter — jobs and tenders lists (#521d84)', () => {
  test('«הכל» clears the promo filter; AND with a field filter; kept after reload @desktop @prod-safe #521d84', async ({ page }) => {
    const sidebar = page.getByRole('complementary');
    const section = sidebar.getByRole('button', { name: SECTION, exact: true });
    const option = (name: string) => sidebar.getByRole('checkbox', { name, exact: true });
    const openSection = async () => {
      if ((await section.getAttribute('aria-expanded')) !== 'true') await section.click();
      await expect(section).toHaveAttribute('aria-expanded', 'true');
    };
    const chip = page.getByRole('button', { name: 'הסרת הסינון: ללא קידום', exact: true });
    const count = page.getByText(/^\d+ תוצאות$/);
    const readCount = async () => Number((await count.innerText()).match(/\d+/)![0]);
    const cards = page.getByRole('main').getByRole('link', { name: /העתקת המספר J-\d+/ });

    // 1. Open /collaborations, tick field «טכנולוגיה…»; note count F
    await page.goto('/collaborations');
    await expect(count).toBeVisible();
    await sidebar.getByRole('checkbox', { name: TECH, exact: true }).click();
    await expect(page).toHaveURL(/[?&]fields=technology(&|$)/);
    await expect(cards.first()).toBeVisible();
    await expect
      .poll(async () => (await cards.allInnerTexts()).filter((t) => !t.includes(TECH)).length)
      .toBe(0);
    const f = await readCount();

    // 2. «מסלול קידום והפצה» → «ללא קידום»; note count P
    await openSection();
    await option('ללא קידום').click();
    await expect(page).toHaveURL(/[?&]promo=[^&]+/);
    await expect(page).toHaveURL(/[?&]fields=technology(&|$)/);
    await expect(chip).toBeVisible();

    // Expected: P ≤ F, every card has the technology field (AND, AC5); no promoted («משרה חמה») cards
    await expect.poll(readCount).toBeLessThanOrEqual(f);
    const p = await readCount();
    await expect
      .poll(async () => {
        const texts = await cards.allInnerTexts();
        const bad = texts.filter((t) => !t.includes(TECH) || t.includes('משרה חמה'));
        return bad.length === 0 ? 'ok' : `bad cards: ${bad.map((t) => t.slice(0, 50)).join(' | ')}`;
      })
      .toBe('ok');
    const promoValue = new URL(page.url()).searchParams.get('promo');

    // 3. Reload
    await page.reload();

    // Expected: URL keeps promo= and the field; «ללא קידום» selected; count P (AC6)
    await expect(count).toBeVisible();
    expect(new URL(page.url()).searchParams.get('promo')).toBe(promoValue);
    await expect(page).toHaveURL(/[?&]fields=technology(&|$)/);
    await expect.poll(readCount).toBe(p);
    await openSection();
    await expect(option('ללא קידום')).toBeChecked();
    await expect(option('הכל')).not.toBeChecked();
    await expect(sidebar.getByRole('checkbox', { name: TECH, exact: true })).toBeChecked();

    // 4. Choose «הכל»
    await option('הכל').click();

    // Expected: promo removed, chip gone, count F, field filter stays
    await expect.poll(() => new URL(page.url()).searchParams.has('promo')).toBe(false);
    await expect(page).toHaveURL(/[?&]fields=technology(&|$)/);
    await expect(chip).toHaveCount(0);
    await expect.poll(readCount).toBe(f);
    await expect(sidebar.getByRole('checkbox', { name: TECH, exact: true })).toBeChecked();
  });
});
